#if DEBUG
import Foundation
import QuickrCore
import QuickrTestSupport
import Testing

@testable import QuickrData

/// The DEBUG demo reminder (`DueReminder`, `-QuickrDemoNotify`) builds the notification the
/// server's `apns.render` sends: every case of shared/fixtures/apns-payload-vectors.json
/// (generated by backend/tests/test_apns_payload_vectors.py).
@Suite(.timeLimit(.minutes(5))) struct DueReminderVectorTests {
    static let cases: [Case] = {
        do {
            return try JSONDecoder().decode(Vectors.self, from: Fixtures.data("apns-payload-vectors.json")).cases
        } catch {
            fatalError("apns-payload-vectors.json: \(error)")
        }
    }()

    @Test func hasTheVectors() {
        #expect(Self.cases.count >= 8)
        #expect(Self.cases.contains { $0.expected.aps.category == nil })
        #expect(Self.cases.contains { $0.expected.aps.alert.title.hasSuffix("…") })
    }

    @Test(arguments: cases)
    func matchesTheServersPayload(_ vector: Case) throws {
        let category = NotificationCategory(
            serverId: vector.serverId, topicId: vector.topicId, version: vector.version,
            questions: vector.questions.map { $0.toDomain() }, counts: vector.counts, last: vector.last)
        let request = DueReminder.request(
            serverId: vector.serverId, topicId: vector.topicId, topicSlug: vector.topicSlug, title: vector.title,
            body: vector.body, version: vector.version, dueSince: try Self.instant(vector.dueSince),
            category: category)
        let aps = vector.expected.aps
        #expect(request.title == aps.alert.title, "\(vector.name): title")
        #expect(request.body == aps.alert.body, "\(vector.name): body")
        #expect(request.categoryIdentifier == aps.category, "\(vector.name): category")
        #expect(request.threadIdentifier == aps.threadId, "\(vector.name): thread")
        #expect(request.sound == (aps.sound == "default"), "\(vector.name): sound")
        #expect(request.quickr == vector.expected.quickr, "\(vector.name): quickr")
        #expect(request.quickr?.origin == .remote, "it stands in for a push")
        // What the handler reads back from userInfo is the server's object.
        let reread = try JSONDecoder().decode(
            QuickrNotificationInfo.self, from: JSONEncoder().encode(try #require(request.quickr)))
        #expect(reread == vector.expected.quickr, "\(vector.name): quickr survives userInfo")
        #expect(request.id == "due-\(vector.topicId)-\(vector.expected.quickr.dueSince ?? "")")
    }

    /// A new `aps` key in the server's payload is either rendered here or listed as delivery-only.
    @Test func everyApsKeyIsAccountedFor() throws {
        let raw = try JSONSerialization.jsonObject(with: Fixtures.data("apns-payload-vectors.json")) as? [String: Any]
        let cases = try #require(raw?["cases"] as? [[String: Any]])
        let rendered: Set<String> = ["alert", "category", "thread-id", "sound"]
        let deliveryOnly: Set<String> = ["mutable-content", "relevance-score"]
        for item in cases {
            let aps = try #require((item["expected"] as? [String: Any])?["aps"] as? [String: Any])
            #expect(Set(aps.keys).subtracting(rendered.union(deliveryOnly)).isEmpty, "\(item["name"] ?? "")")
        }
    }

    // MARK: - The demo's slot and body (the scheduler's tick, through the due port)

    static let now = Date(timeIntervalSince1970: 1_792_569_600)  // 2026-10-21T08:00:00Z

    static func topic(schedule: Schedule?, lastMinutesAgo: Double?) -> Topic {
        let glasses = Question(key: "glasses", label: "Glasses", kind: .int(.init(min: 0, max: 20, unit: "glasses")))
        return Topic(
            id: UUID(uuidString: "00000000-0000-4000-8000-000000000002")!, slug: "water", name: "Water",
            currentVersion: 1, revision: 1, questionCount: 1,
            lastCapturedAt: lastMinutesAgo.map { now.addingTimeInterval(-$0 * 60) },
            createdAt: now.addingTimeInterval(-30 * 86_400), updatedAt: now, schedule: schedule,
            scheduleUpdatedAt: now.addingTimeInterval(-30 * 86_400), questions: [glasses])
    }

    @Test func aDueTopicGetsItsSlotAndTheSchedulersBody() throws {
        let topic = Self.topic(schedule: .interval(.init(everyMinutes: 120, timezone: "UTC")), lastMinutesAgo: 130)
        let category = NotificationCategory(
            serverId: "demo-server", topicId: topic.id.wireString, version: 1, questions: topic.questions,
            last: .int(3))
        let request = DueReminder.request(serverId: "demo-server", topic: topic, category: category, now: Self.now)
        // Due 120 min after the last entry: 10 minutes ago, so still "Time to log".
        #expect(request.quickr?.dueSince == "2026-10-21T07:50:00Z")
        #expect(request.body == "Time to log")
        #expect(request.title == "Water")
        #expect(request.categoryIdentifier == category?.id)
        #expect(
            request.quickr?.slot
                == ReminderSlot(
                    serverId: "demo-server", topicId: topic.id.wireString, dueSince: "2026-10-21T07:50:00Z"))

        let overdue = Self.topic(schedule: .interval(.init(everyMinutes: 60, timezone: "UTC")), lastMinutesAgo: 180)
        #expect(
            DueReminder.request(serverId: "s", topic: overdue, category: nil, now: Self.now).body
                == "Overdue since 06:00")
    }

    @Test func aTopicThatIsntDueGetsASlotNow() {
        for topic in [
            Self.topic(schedule: nil, lastMinutesAgo: 5),
            Self.topic(schedule: .interval(.init(everyMinutes: 120, timezone: "UTC")), lastMinutesAgo: 5),
        ] {
            let request = DueReminder.request(
                serverId: "s", topic: topic, category: nil, now: Self.now.addingTimeInterval(0.9))
            #expect(request.quickr?.dueSince == "2026-10-21T08:00:00Z", "whole seconds, rounded down")
            #expect(request.body == "Time to log")
            #expect(request.categoryIdentifier == nil)
        }
    }

    @Test func titlesAreCutAtOneHundredTwentyScalars() {
        let exact = String(repeating: "é", count: 120)
        #expect(DueReminder.cut(exact, to: 120) == exact)
        let cut = DueReminder.cut(exact + "x", to: 120)
        #expect(cut.unicodeScalars.count == 120 && cut.hasSuffix("…"))
    }

    static func instant(_ text: String) throws -> Date {
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        if let date = formatter.date(from: text) { return date }
        return try Date(text, strategy: .iso8601)
    }

    // MARK: - The fixture

    struct Vectors: Decodable { var cases: [Case] }

    struct Case: Decodable, Sendable, CustomTestStringConvertible {
        var name: String
        var serverId: String
        var topicId: String
        var topicSlug: String
        var title: String
        var body: String
        var version: Int
        var dueSince: String
        var questions: [QuestionDTO]
        var counts: [String: Int]
        var last: AnswerValue?
        var expected: Payload

        var testDescription: String { name }

        struct Payload: Decodable, Sendable {
            var aps: Aps
            var quickr: QuickrNotificationInfo
        }

        struct Aps: Decodable, Sendable {
            var alert: Alert
            var category: String?
            var threadId: String?
            var sound: String?

            struct Alert: Decodable, Sendable {
                var title: String
                var body: String
            }

            enum CodingKeys: String, CodingKey {
                case alert, category, sound
                case threadId = "thread-id"
            }
        }

        enum CodingKeys: String, CodingKey {
            case name, title, body, version, questions, counts, last, expected
            case serverId = "server_id"
            case topicId = "topic_id"
            case topicSlug = "topic_slug"
            case dueSince = "due_since"
        }

        init(from decoder: any Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            name = try c.decode(String.self, forKey: .name)
            serverId = try c.decode(String.self, forKey: .serverId)
            topicId = try c.decode(String.self, forKey: .topicId)
            topicSlug = try c.decode(String.self, forKey: .topicSlug)
            title = try c.decode(String.self, forKey: .title)
            body = try c.decode(String.self, forKey: .body)
            version = try c.decode(Int.self, forKey: .version)
            dueSince = try c.decode(String.self, forKey: .dueSince)
            questions = try c.decode([QuestionDTO].self, forKey: .questions)
            counts = try c.decode([String: Int].self, forKey: .counts)
            expected = try c.decode(Payload.self, forKey: .expected)
            // As NotificationVectorTests reads it: an int stays exact, a string isn't a number.
            if try c.decodeNil(forKey: .last) {
                last = nil
            } else if let n = try? c.decode(Int.self, forKey: .last) {
                last = .int(n)
            } else if let x = try? c.decode(Double.self, forKey: .last) {
                last = .double(x)
            } else {
                last = .string(try c.decode(String.self, forKey: .last))
            }
        }
    }
}
#endif
